mkitem!{declare_lint ! { # [doc = " The `unqualified_local_imports` lint checks for `use` items that import a local item using a"] # [doc = " path that does not start with `self::`, `super::`, or `crate::`."] # [doc = ""] # [doc = " ### Example"] # [doc = ""] # [doc = " ```rust,edition2018"] # [doc = " #![feature(unqualified_local_imports)]"] # [doc = " #![warn(unqualified_local_imports)]"] # [doc = ""] # [doc = " mod localmod {"] # [doc = "     pub struct S;"] # [doc = " }"] # [doc = ""] # [doc = " use localmod::S;"] # [doc = " # // We have to actually use `S`, or else the `unused` warnings suppress the lint we care about."] # [doc = " # pub fn main() {"] # [doc = " #     let _x = S;"] # [doc = " # }"] # [doc = " ```"] # [doc = ""] # [doc = " {{produces}}"] # [doc = ""] # [doc = " ### Explanation"] # [doc = ""] # [doc = " This lint is meant to be used with the (unstable) rustfmt setting `group_imports = \"StdExternalCrate\"`."] # [doc = " That setting makes rustfmt group `self::`, `super::`, and `crate::` imports separately from those"] # [doc = " referring to other crates. However, rustfmt cannot know whether `use c::S;` refers to a local module `c`"] # [doc = " or an external crate `c`, so it always gets categorized as an import from another crate."] # [doc = " To ensure consistent grouping of imports from the local crate, all local imports must"] # [doc = " start with `self::`, `super::`, or `crate::`. This lint can be used to enforce that style."] pub UNQUALIFIED_LOCAL_IMPORTS , Allow , "`use` of a local item without leading `self::`, `super::`, or `crate::`" , @ feature_gate = unqualified_local_imports ; }}
